if (std::vector<Point_2>::size(polygon) < 3)
    return false;

std::vector<Point_2> points = polygon;
std::vector<Point_2>::iterator it = std::vector<Point_2>::begin(points);
std::vector<Point_2>::iterator prev = std::vector<Point_2>::end(points);
prev--;
std::vector<Point_2>::iterator next = std::vector<Point_2>::begin(points);
std::advance(next, 1);

int prev_cross = 0;
int curr_cross = 0;

for (it = std::vector<Point_2>::begin(points); it != std::vector<Point_2>::end(points); ++it) {
    if (next == std::vector<Point_2>::end(points))
        next = std::vector<Point_2>::begin(points);

    Point_2 p0 = *prev;
    Point_2 p1 = *it;
    Point_2 p2 = *next;

    CGAL::Cross_product_result cross = CGAL::cross_product(p1 - p0, p2 - p1);

    if (cross == CGAL::COLLINEAR)
        return false;

    if (prev_cross == 0)
        prev_cross = cross > 0 ? 1 : -1;
    else if (curr_cross != 0 && (cross > 0 ? 1 : -1) != prev_cross)
        return false;

    curr_cross = cross > 0 ? 1 : -1;
    prev = it;
    next++;
}

return true;
// END_CODE

